const EFFORT_OPTIONS: Array<{ value: Effort; blurb: string }> = [
  { value: "low", blurb: "quick answers · 6 tool rounds" },
  { value: "medium", blurb: "balanced · 14 tool rounds" },
  { value: "high", blurb: "thorough · 28 tool rounds" },
  { value: "max", blurb: "exhaustive · 50 tool rounds" },
  { value: "ultracode", blurb: "plans · todos · parallel agents · unlimited rounds" },
];

/** Tokens-per-second meter: rate averaged over the last 3s, trend compares
 * the last 3s window against the 3s before it. */
class TpsMeter {
  private stamps: number[] = [];
  record(): void {
    this.stamps.push(Date.now());
    if (this.stamps.length > 20000) this.stamps.splice(0, 10000);
  }
  reset(): void {
    this.stamps = [];
  }
  tps(): number {
    const now = Date.now();
    let n = 0;
    for (let i = this.stamps.length - 1; i >= 0 && now - this.stamps[i] <= 3000; i--) n++;
    return n / 3;
  }
  trend(): "up" | "down" {
    const now = Date.now();
    let last3 = 0;
    let prev3 = 0;
    for (let i = this.stamps.length - 1; i >= 0; i--) {
      const age = now - this.stamps[i];
      if (age <= 3000) last3++;
      else if (age <= 6000) prev3++;
      else break;
    }
    return last3 >= prev3 ? "up" : "down";
  }
}

