20	export const COMMANDS: CommandDef[] = [
21	  { name: "help", description: "show commands and keybindings" },
22	  { name: "clear", description: "clear conversation and screen" },
23	  { name: "compact", description: "summarize history to free context" },
24	  { name: "effort", description: "set effort: low | medium | high | max | ultracode" },
