38	  { name: "quit", description: "exit glint" },
39	  { name: "goal", description: "set or clear a goal: /goal <text> | /goal clear" },
40	  { name: "fast", description: "use compound-mini for all calls (fastest)" },
41	  { name: "smart", description: "use compound for all calls (smartest)" },
42	  { name: "default", description: "restore default model config" },
43	  { name: "auto", description: "toggle auto-mode: pre-checks if tool use is needed before each turn" },
44	];
45	
46	/** Resolve a possibly-abbreviated command name: exact match wins, then a
47	 * unique prefix; returns null when unknown or ambiguous. */
48	export function resolveCommand(name: string): string | null {
49	  if (COMMANDS.some((c) => c.name === name)) return name;
50	  const matches = COMMANDS.filter((c) => c.name.startsWith(name));
51	  return matches.length === 1 ? matches[0].name : null;
52	}
53	
54	export function runCommand(
55	  input: string,
56	  ctx: { usage: { prompt: number; completion: number; total: number }; ctxTokens: number; cost: number },
57	): CommandResult {
58	  const [cmd, ...rest] = input.slice(1).split(/\s+/);
59	  const arg = rest.join(" ").trim();
60	  const config = loadConfig();
61	
62	  switch (cmd) {
63	    case "help":
64	      return {
65	        kind: "text",
66	        text: [
67	          `**glint v${VERSION}** — Glint Research`,
68	          "",
69	          ...COMMANDS.map((c) => `  **/${c.name}** — ${c.description}`),
70	          "",
71	          "  **!cmd** — run a shell command directly",
72	          "  **esc** — interrupt the agent · **ctrl+c ×2** — quit",
73	          "  **↑/↓** — input history, or navigate / suggestions · **tab** complete · **enter** run selected",
74	          "  **ctrl+t** — expand/collapse thinking · **ctrl+a/e/u/w** — line editing",
75	          "",
76	          "Skills become commands: save one and invoke it as /name.",
77	        ].join("\n"),
78	      };
79	    case "clear":
80	      return { kind: "clear" };
81	    case "compact":
