import { EFFORT_LEVELS, MODEL, SUBAGENT_MODEL, VERSION, type Effort, type ModelMode, effectiveModels, loadConfig, saveConfig } from "./core/config.ts";
import { formatCost } from "./core/pricing.ts";
import { diagnosticsPath, verifyChain } from "./core/diagnostics.ts";
import { memoryPath, readMemory } from "./core/memory.ts";
import { listSessions } from "./core/session.ts";
import { listSkills } from "./core/skills.ts";

export interface CommandResult {
  kind: "text" | "clear" | "quit" | "intro" | "compact" | "resume" | "submit" | "effort-menu" | "goal-set" | "goal-clear";
  text?: string;
  resumeId?: string;
  goal?: string;
}

export interface CommandDef {
  name: string;
  description: string;
}

export const COMMANDS: CommandDef[] = [
  { name: "help", description: "show commands and keybindings" },
  { name: "clear", description: "clear conversation and screen" },
  { name: "compact", description: "summarize history to free context" },
  { name: "effort", description: "set effort: low | medium | high | max | ultracode" },
  { name: "model", description: "show model configuration" },
  { name: "yolo", description: "toggle auto-approve for all actions" },
  { name: "thought-show", description: "show the model's thinking while it works" },
  { name: "thought-hide", description: "hide thinking, show the compact spinner" },
  { name: "diagnostics", description: "diagnostics status + verify trace chain" },
  { name: "no-diagnostics", description: "opt out of diagnostic traces" },
  { name: "memory", description: "show persistent memory" },
  { name: "skills", description: "list saved skills" },
  { name: "sessions", description: "list recent sessions" },
  { name: "resume", description: "resume a session: /resume <id>" },
  { name: "usage", description: "token usage this session" },
  { name: "init", description: "generate an AGENTS.md for this project" },
  { name: "intro", description: "replay the startup animation" },
  { name: "quit", description: "exit glint" },
  { name: "goal", description: "set or clear a goal: /goal <text> | /goal clear" },
  { name: "fast", description: "use compound-mini for all calls (fastest)" },
  { name: "smart", description: "use compound for all calls (smartest)" },
  { name: "default", description: "restore default model config" },
  { name: "auto", description: "toggle auto-mode: pre-checks if tool use is needed before each turn" },
];

/** Resolve a possibly-abbreviated command name: exact match wins, then a
 * unique prefix; returns null when unknown or ambiguous. */
export function resolveCommand(name: string): string | null {
  if (COMMANDS.some((c) => c.name === name)) return name;
  const matches = COMMANDS.filter((c) => c.name.startsWith(name));
  return matches.length === 1 ? matches[0].name : null;
}

export function runCommand(
  input: string,
  ctx: { usage: { prompt: number; completion: number; total: number }; ctxTokens: number; cost: number },
): CommandResult {
  const [cmd, ...rest] = input.slice(1).split(/\s+/);
  const arg = rest.join(" ").trim();
  const config = loadConfig();

  switch (cmd) {
    case "help":
      return {
        kind: "text",
        text: [
          `**glint v${VERSION}** — Glint Research`,
          "",
          ...COMMANDS.map((c) => `  **/${c.name}** — ${c.description}`),
          "",
          "  **!cmd** — run a shell command directly",
          "  **esc** — interrupt the agent · **ctrl+c ×2** — quit",
          "  **↑/↓** — input history, or navigate / suggestions · **tab** complete · **enter** run selected",
          "  **ctrl+t** — expand/collapse thinking · **ctrl+a/e/u/w** — line editing",
          "",
          "Skills become commands: save one and invoke it as /name.",
        ].join("\n"),
      };
    case "clear":
      return { kind: "clear" };
    case "compact":
      return { kind: "compact" };
    case "effort": {
      if (!arg) return { kind: "effort-menu" };
      if (!(arg in EFFORT_LEVELS)) {
        return { kind: "text", text: `unknown effort "${arg}" — use: ${Object.keys(EFFORT_LEVELS).join(", ")}` };
      }
      saveConfig({ effort: arg as Effort });
      const rounds = EFFORT_LEVELS[arg as Effort].maxIterations;
      return {
        kind: "text",
        text: `effort set to **${arg}** (${Number.isFinite(rounds) ? `${rounds} tool rounds per turn` : "unlimited tool rounds"})`,
      };
    }
    case "thought-show":
      saveConfig({ thoughts: true });
      return { kind: "text", text: "thinking **shown** — click the thought box (or ctrl+t) to expand it." };
    case "thought-hide":
      saveConfig({ thoughts: false });
      return { kind: "text", text: "thinking **hidden** — you'll see the compact spinner with live tps." };
    case "model": {
      const m = effectiveModels();
      const extra = config.modelMode !== "default" ? ` (mode: ${config.modelMode})` : "";
      return {
        kind: "text",
        text: `agent: **${m.agent}**\nsubagent: **${m.subagent}**\nmode: **${config.modelMode}**${extra}\nprovider: Groq (free tier) — $0.00, always`,
      };
    }
    case "yolo": {
      const next = !config.yolo;
      saveConfig({ yolo: next });
      return {
        kind: "text",
        text: next
          ? "yolo **on** — all tool actions auto-approved. Live dangerously."
          : "yolo **off** — shell commands and writes ask first.",
      };
    }
    case "diagnostics": {
      if (!config.diagnostics) {
        saveConfig({ diagnostics: true });
        return { kind: "text", text: "diagnostics **enabled** — traces resume." };
      }
      const check = verifyChain();
      return {
        kind: "text",
        text: [
          `diagnostics: **on** (local-only, never leaves this machine)`,
          `file: ${diagnosticsPath()}`,
          `records today: ${check.records} · chain integrity: ${check.ok ? "✓ intact" : `✗ BROKEN at record ${check.brokenAt}`}`,
          `each record is SHA-256 chained to the previous — tampering is detectable.`,
          `opt out: /no-diagnostics`,
        ].join("\n"),
      };
    }
    case "no-diagnostics":
      saveConfig({ diagnostics: false });
      return {
        kind: "text",
        text: "diagnostics **disabled** — no further traces will be written. Re-enable with /diagnostics.",
      };
    case "memory": {
      const mem = readMemory();
      return {
        kind: "text",
        text: mem
          ? `**memory** (${memoryPath()}):\n\n${mem}`
          : `memory is empty — ask me to remember something, or I'll save useful facts as we work. (${memoryPath()})`,
      };
    }
    case "skills": {
      const skills = listSkills();
      return {
        kind: "text",
        text:
          skills.length > 0
            ? `**skills:**\n${skills.map((s) => `  /${s.name} — ${s.description}`).join("\n")}`
            : 'no skills yet — ask me to "save this as a skill called X" after a task.',
      };
    }
    case "sessions": {
      const sessions = listSessions();
      return {
        kind: "text",
        text:
          sessions.length > 0
            ? `**recent sessions** (resume with /resume <id>):\n${sessions
                .map((s) => `  ${s.id} · ${s.updated?.slice(0, 16).replace("T", " ")} · ${s.messages} msgs · ${s.title}`)
                .join("\n")}`
            : "no saved sessions yet.",
      };
    }
    case "resume":
      if (!arg) return { kind: "text", text: "usage: /resume <id> — see /sessions" };
      return { kind: "resume", resumeId: arg };
    case "usage":
      return {
        kind: "text",
        text: [
          `session tokens — prompt: **${fmt(ctx.usage.prompt)}** · completion: **${fmt(ctx.usage.completion)}** · total: **${fmt(ctx.usage.total)}**`,
          `context now: ~${fmt(ctx.ctxTokens)} tokens`,
          `compute value: **${formatCost(ctx.cost)}** at Groq list rates (compound passes through to its underlying models) — billed to you: **$0.00**, free tier.`,
        ].join("\n"),
      };
    case "init":
      return {
        kind: "submit",
        text: "Inspect this repository (list the root, read the key config/build files) and write a concise AGENTS.md at the repo root: what the project is, the exact commands to build/test/run it, code conventions you can infer, and any gotchas. Keep it under 60 lines. If AGENTS.md already exists, improve it instead.",
      };
    case "fast":
      saveConfig({ modelMode: "fast" as ModelMode });
      return { kind: "text", text: `model mode: **fast** — all calls use ${SUBAGENT_MODEL} (fastest, cheapest).` };
    case "smart":
      saveConfig({ modelMode: "smart" as ModelMode });
      return { kind: "text", text: `model mode: **smart** — all calls use ${MODEL} (highest quality).` };
    case "default":
      saveConfig({ modelMode: "default" as ModelMode });
      return { kind: "text", text: `model mode: **default** — agent ${MODEL}, subagents ${SUBAGENT_MODEL}.` };
    case "auto": {
      const next = !config.auto;
      saveConfig({ auto: next });
      return {
        kind: "text",
        text: next
          ? "auto-mode **on** — before each turn, a lightweight check decides if tools (writes/edits/commands) are actually needed. If the request is just a question, the agent answers in-chat without touching files."
          : "auto-mode **off** — all tools available as normal.",
      };
    }
    case "goal":
      if (!arg) {
        return { kind: "text", text: "usage: /goal <text> — sets a goal the agent must achieve. /goal clear — removes it.\nOn high+ effort, goals are auto-set from your prompt." };
      }
      if (arg === "clear" || arg === "off") {
        return { kind: "goal-clear" };
      }
      return { kind: "goal-set", goal: arg };
    case "intro":
      return { kind: "intro" };
    case "quit":
    case "exit":
      return { kind: "quit" };
    default:
      return { kind: "text", text: `unknown command: /${cmd} — try /help` };
  }
}

function fmt(n: number): string {
  return n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n);
}

