5	/** Full markdown renderer for transcript messages: headers, lists, code
6	 * fences, tables, blockquotes, rules, links, and inline styling. */
7	export function Markdown({ text }: { text: string }): React.ReactElement {
8	  const lines = text.split("\n");
9	  const blocks: React.ReactElement[] = [];
10	  let i = 0;
11	  let key = 0;
12	
13	  while (i < lines.length) {
14	    const line = lines[i];
15	
16	    const fence = line.match(/^\s*```(\w*)\s*$/);
17	    if (fence) {
18	      const lang = fence[1];
19	      const code: string[] = [];
20	      i++;
21	      while (i < lines.length && !/^\s*```\s*$/.test(lines[i])) {
22	        code.push(lines[i]);
23	        i++;
24	      }
25	      i++;
26	      blocks.push(
27	        <Box key={key++} flexDirection="column" marginLeft={1}>
28	          <Text color={theme.faint}>┌{lang ? ` ${lang}` : ""}</Text>
29	          {code.map((cl, j) => (
30	            <Text key={j}>
31	              <Text color={theme.faint}>│ </Text>
32	              <Text color={theme.amber}>{cl || " "}</Text>
33	            </Text>
34	          ))}
35	          <Text color={theme.faint}>└</Text>
36	        </Box>,
37	      );
