import React from "react";
import { Box, Text } from "ink";
import { theme } from "../theme.ts";

/** Full markdown renderer for transcript messages: headers, lists, code
 * fences, tables, blockquotes, rules, links, and inline styling. */
export function Markdown({ text }: { text: string }): React.ReactElement {
  const lines = text.split("\n");
  const blocks: React.ReactElement[] = [];
  let i = 0;
  let key = 0;

  while (i < lines.length) {
    const line = lines[i];

    const fence = line.match(/^\s*```(\w*)\s*$/);
    if (fence) {
      const lang = fence[1];
      const code: string[] = [];
      i++;
      while (i < lines.length && !/^\s*```\s*$/.test(lines[i])) {
        code.push(lines[i]);
        i++;
      }
      i++;
      blocks.push(
        <Box key={key++} flexDirection="column" marginLeft={1}>
          <Text color={theme.faint}>┌{lang ? ` ${lang}` : ""}</Text>
          {code.map((cl, j) => (
            <Text key={j}>
              <Text color={theme.faint}>│ </Text>
              <Text color={theme.amber}>{cl || " "}</Text>
            </Text>
          ))}
          <Text color={theme.faint}>└</Text>
        </Box>,
      );
      continue;
    }

    if (isTableRow(line) && i + 1 < lines.length && isTableSeparator(lines[i + 1])) {
      const header = splitRow(line);
      i += 2;
      const rows: string[][] = [];
      while (i < lines.length && isTableRow(lines[i])) {
        rows.push(splitRow(lines[i]));
        i++;
      }
      blocks.push(<Table key={key++} header={header} rows={rows} />);
      continue;
    }

    if (/^\s*(-{3,}|\*{3,}|_{3,})\s*$/.test(line)) {
      blocks.push(
        <Text key={key++} color={theme.faint}>
          {"─".repeat(40)}
        </Text>,
      );
      i++;
      continue;
    }

    const header = line.match(/^(#{1,6})\s+(.*)$/);
    if (header) {
      blocks.push(
        <Text key={key++} bold color={theme.orange}>
          {header[1].length <= 2 ? header[2].toUpperCase() : header[2]}
        </Text>,
      );
      i++;
      continue;
    }

    const quote = line.match(/^\s*>\s?(.*)$/);
    if (quote) {
      blocks.push(
        <Text key={key++}>
          <Text color={theme.orange}>▌ </Text>
          <Text color={theme.dim} italic>
            {inline(quote[1])}
          </Text>
        </Text>,
      );
      i++;
      continue;
    }

    const bullet = line.match(/^(\s*)[-*+]\s+(.*)$/);
    if (bullet) {
      const depth = Math.floor(bullet[1].length / 2);
      blocks.push(
        <Text key={key++}>
          {"  ".repeat(depth + (depth > 0 ? 1 : 0))}
          <Text color={theme.orange}>{depth > 0 ? "◦ " : "• "}</Text>
          {inline(bullet[2])}
        </Text>,
      );
      i++;
      continue;
    }

    const numbered = line.match(/^(\s*)(\d+)[.)]\s+(.*)$/);
    if (numbered) {
      blocks.push(
        <Text key={key++}>
          {numbered[1]}
          <Text color={theme.orange}>{numbered[2]}. </Text>
          {inline(numbered[3])}
        </Text>,
      );
      i++;
      continue;
    }

    blocks.push(<Text key={key++}>{line.trim() === "" ? " " : inline(line)}</Text>);
    i++;
  }

  return <Box flexDirection="column">{blocks}</Box>;
}

function isTableRow(line: string): boolean {
  const t = line.trim();
  return t.startsWith("|") && t.endsWith("|") && t.length > 2;
}

function isTableSeparator(line: string): boolean {
  const t = line.trim();
  return /^\|(\s*:?-{2,}:?\s*\|)+$/.test(t);
}

function splitRow(line: string): string[] {
  const t = line.trim().replace(/^\|/, "").replace(/\|$/, "");
  const cells: string[] = [];
  let cur = "";
  let esc = false;
  for (const ch of t) {
    if (esc) {
      cur += ch;
      esc = false;
      continue;
    }
    if (ch === "\\") {
      esc = true;
      continue;
    }
    if (ch === "|") {
      cells.push(cur.trim());
      cur = "";
    } else cur += ch;
  }
  cells.push(cur.trim());
  return cells;
}

const MAX_TABLE_WIDTH = 100;

function Table({ header, rows }: { header: string[]; rows: string[][] }): React.ReactElement {
  const cols = header.length;
  const widths = header.map((h, c) => {
    let w = plain(h).length;
    for (const r of rows) w = Math.max(w, plain(r[c] ?? "").length);
    return w;
  });
  // Shrink the widest columns until the table fits.
  let total = widths.reduce((a, b) => a + b, 0) + cols * 3 + 1;
  while (total > MAX_TABLE_WIDTH) {
    const maxIdx = widths.indexOf(Math.max(...widths));
    if (widths[maxIdx] <= 12) break;
    widths[maxIdx]--;
    total--;
  }
  const fit = (s: string, w: number): string => {
    const p = plain(s);
    if (p.length <= w) return p + " ".repeat(w - p.length);
    return p.slice(0, Math.max(0, w - 1)) + "…";
  };
  const border = (l: string, m: string, r: string) =>
    l + widths.map((w) => "─".repeat(w + 2)).join(m) + r;

  return (
    <Box flexDirection="column" marginLeft={1}>
      <Text color={theme.faint}>{border("┌", "┬", "┐")}</Text>
      <Text>
        <Text color={theme.faint}>│ </Text>
        {header.map((h, c) => (
          <Text key={c}>
            <Text bold color={theme.orange}>
              {fit(h, widths[c])}
            </Text>
            <Text color={theme.faint}> │ </Text>
          </Text>
        ))}
      </Text>
      <Text color={theme.faint}>{border("├", "┼", "┤")}</Text>
      {rows.map((r, ri) => (
        <Text key={ri}>
          <Text color={theme.faint}>│ </Text>
          {widths.map((w, c) => (
            <Text key={c}>
              <Text color={theme.ink}>{fit(r[c] ?? "", w)}</Text>
              <Text color={theme.faint}> │ </Text>
            </Text>
          ))}
        </Text>
      ))}
      <Text color={theme.faint}>{border("└", "┴", "┘")}</Text>
    </Box>
  );
}

function plain(text: string): string {
  return text
    .replace(/\*\*([^*]+)\*\*/g, "$1")
    .replace(/\*([^*]+)\*/g, "$1")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/~~([^~]+)~~/g, "$1")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1");
}

function inline(text: string): React.ReactNode[] {
  const nodes: React.ReactNode[] = [];
  const re = /(\*\*[^*]+\*\*|`[^`]+`|~~[^~]+~~|\[[^\]]+\]\([^)]+\)|\*[^*\s][^*]*\*|_[^_\s][^_]*_)/g;
  let last = 0;
  let key = 0;
  for (const m of text.matchAll(re)) {
    if (m.index! > last) nodes.push(<Text key={key++}>{text.slice(last, m.index)}</Text>);
    const tok = m[0];
    if (tok.startsWith("**")) {
      nodes.push(
        <Text key={key++} bold color={theme.ink}>
          {tok.slice(2, -2)}
        </Text>,
      );
    } else if (tok.startsWith("`")) {
      nodes.push(
        <Text key={key++} color={theme.amber}>
          {tok.slice(1, -1)}
        </Text>,
      );
    } else if (tok.startsWith("~~")) {
      nodes.push(
        <Text key={key++} strikethrough color={theme.dim}>
          {tok.slice(2, -2)}
        </Text>,
      );
    } else if (tok.startsWith("[")) {
      const lm = tok.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      nodes.push(
        <Text key={key++}>
          <Text color={theme.cyan} underline>
            {lm?.[1] ?? tok}
          </Text>
          <Text color={theme.faint}> ({lm?.[2] ?? ""})</Text>
        </Text>,
      );
    } else {
      nodes.push(
        <Text key={key++} italic>
          {tok.slice(1, -1)}
        </Text>,
      );
    }
    last = m.index! + tok.length;
  }
  if (last < text.length) nodes.push(<Text key={key++}>{text.slice(last)}</Text>);
  return nodes;
}

