const liveRef = useRef<Item[]>([]);
const staticRef = useRef<Item[]>([]);

// Transcript items live in the docked region (visible above the input) and
// overflow into Static scrollback oldest-first, so recent output is always
// on screen and full history is always in the terminal's own scrollback.
const estimateRows = useCallback((item: Item): number => {
  if (item.kind === "banner") return 4;
  const cols = Math.max(40, (process.stdout.columns ?? 100) - 6);
  const textRows = item.text
    ? item.text.split("\n").reduce((a, l) => a + Math.max(1, Math.ceil(l.length / cols)), 0)
    : 0;
  if (item.kind === "tool") return 1 + textRows;
  return textRows + 1;
}, []);

const liveBudget = useCallback((isRunning: boolean): number => {
  const r = rowsRef.current;
  return isRunning ? Math.max(4, Math.floor((r - 12) / 2)) : Math.max(6, r - 12);
}, []);

const runningRef = useRef(false);

const push = useCallback(
  (item: Omit<Item, "id">) => {
    const next: Item = { ...item, id: nextId++ };
    let live = [...liveRef.current.filter((it) => !it.tailOnly), next];
    const budget = liveBudget(runningRef.current);
    const flushed: Item[] = [];
    let total = live.reduce((a, it) => a + estimateRows(it), 0);
    while (total > budget && live.length > 1) {
      const old = live.shift()!;
      flushed.push(old);
      total -= estimateRows(old);
    }
    if (live.length === 1 && estimateRows(live[0]) > budget) {
      // A single oversized item: full copy goes to scrollback now, the
      // docked region shows just its tail.
      const it = live[0];
      flushed.push(it);
      const cols = Math.max(40, (process.stdout.columns ?? 100) - 6);
      const lines = it.text.split("\n");
      const kept: string[] = [];
      let rows = 0;
      for (let i = lines.length - 1; i >= 0 && rows < budget - 2; i--) {
        rows += Math.max(1, Math.ceil(lines[i].length / cols));
        kept.unshift(lines[i]);
      }
      live = [{ ...it, id: nextId++, text: "…\n" + kept.join("\n"), tailOnly: true }];
    }
    const dropped = liveRef.current.filter((it) => it.tailOnly);
    liveRef.current = live;
    if (flushed.length > 0 || dropped.length > 0) {
      staticRef.current = [...staticRef.current, ...flushed];
      setStaticItems(staticRef.current);
    }
    setLiveItems(live);
  },
  [estimateRows, liveBudget],
);

/** Re-trim live items to the current budget (turn start shrinks the budget
 * to make room for the stream/thought area). */
const trimLive = useCallback(() => {
  let live = [...liveRef.current];
  const budget = liveBudget(runningRef.current);
  const flushed: Item[] = [];
  let total = live.reduce((a, it) => a + estimateRows(it), 0);
  while (total > budget && live.length > 0) {
    const old = live.shift()!;
    if (!old.tailOnly) flushed.push(old);
    total -= estimateRows(old);
  }
  if (flushed.length > 0) {
    staticRef.current = [...staticRef.current, ...flushed];
    setStaticItems(staticRef.current);
  }
  liveRef.current = live;
  setLiveItems(live);
}, [estimateRows, liveBudget]);

useEffect(() => {
  if (phase !== "ready") return;
  push({ kind: "banner", text: "" });
  trace("session.start", { mode: "tui" });
  if (opts.resume) {
    const loaded = loadSession(opts.resume);
    if (loaded) {
      stateRef.current.messages = loaded.messages;
      titleRef.current = loaded.title;
      push({
        kind: "notice",
        text: `resumed session ${opts.resume} — "${loaded.title}" (${loaded.messages.length} messages)`,
      });
    } else {
      push({ kind: "error", text: `could not load session ${opts.resume}` });
    }
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [phase]);

// One ticker drives spinner, elapsed, tps, AND the throttled stream flush —
// streaming deltas only repaint ~8x/s instead of per-token, which kills the
// layout flicker on fast generations.
useEffect(() => {
  if (!running) return;
  const started = Date.now();
  const t = setInterval(() => {
    setSpin((s) => s + 1);
    setElapsed(Math.floor((Date.now() - started) / 1000));
    setTps(meterRef.current.tps());
    setTpsTrend(meterRef.current.trend());
    const visible = visiblePrefix(streamBufRef.current);
    // Cap by *rendered* rows: wrapped lines count as multiple rows, or the
    // region overflows the fixed-height frame and corrupts the redraw.
    const cols = Math.max(40, (process.stdout.columns ?? 100) - 6);
    const budget = Math.max(4, Math.floor((rowsRef.current - 12) / 2));
    const lines = visible.split("\n");
    const kept: string[] = [];
    let rows = 0;
    for (let i = lines.length - 1; i >= 0 && rows < budget; i--) {
      rows += Math.max(1, Math.ceil(lines[i].length / cols));
      kept.unshift(lines[i]);
    }
    setStream(kept.join("\n"));
  }, 120);
  return () => clearInterval(t);
}, [running]);

