): Promise<void> {
  const config = loadConfig();
  const { agent: agentModel } = effectiveModels();

  // Auto-mode: quick pre-check with llama-3.1-8b-instant to decide if
  // write/edit/bash tools are actually needed for this request.
  let autoModeReadOnly = false;
  if (config.auto) {
    try {
      const pre = await chat(
        [
          { role: "system", content: "You decide whether a user's request requires creating/editing files or running commands to satisfy it. If the user is just asking a question, asking for analysis, or requesting an explanation — something that can be fully answered in plain text — answer NO. If they explicitly asked to create, write, edit, build, install, deploy, or run something that would change files or execute commands, answer YES. Answer only YES or NO." },
          { role: "user", content: userMessage.slice(0, 2000) },
        ],
        { model: "groq/llama-3.1-8b-instant", maxTokens: 8, temperature: 0 },
      );
      if (/^\s*no\b/i.test(pre.content.trim())) {
        autoModeReadOnly = true;
        cb.onNotice?.("auto-mode: request looks like a question — answering in-chat (no file writes or commands)");
      }
    } catch (e) {
      // If the pre-check fails, allow tools (fail-open).
      trace("auto.precheck_failed", { error: String(e) });
    }
  }

