  // Cells wrap onto extra lines instead of truncating — cut-off table content
  // is unreadable, and the row heights stay correct for Ink's layout.
  const wrapCell = (s: string, w: number): string[] => {
    const words = plain(s).split(/\s+/).filter(Boolean);
    if (words.length === 0) return [""];
    const out: string[] = [];
    let cur = "";
    for (const word of words) {
      if (cur && cur.length + 1 + word.length > w) {
        out.push(cur);
        cur = word;
      } else {
        cur = cur ? `${cur} ${word}` : word;
      }
      while (cur.length > w) {
        out.push(cur.slice(0, w));
        cur = cur.slice(w);
      }
    }
    out.push(cur);
    return out;
  };
  const pad = (s: string, w: number): string => s + " ".repeat(Math.max(0, w - s.length));
  const border = (l: string, m: string, r: string) =>
    l + widths.map((w) => "─".repeat(w + 2)).join(m) + r;
  const renderRow = (cells: string[], bold: boolean, rowKey: string): React.ReactElement[] => {
    const wrapped = widths.map((w, c) => wrapCell(cells[c] ?? "", w));
    const height = Math.max(...wrapped.map((l) => l.length));
    return Array.from({ length: height }, (_, li) => (
      <Text key={`${rowKey}-${li}`}>
        <Text color={theme.faint}>│ </Text>
        {widths.map((w, c) => (
          <Text key={c}>
            <Text bold={bold} color={bold ? theme.orange : theme.ink}>
              {pad(wrapped[c][li] ?? "", w)}
            </Text>
            <Text color={theme.faint}> │ </Text>
          </Text>
        ))}
      </Text>
    ));
  };

  return (
    <Box flexDirection="column" marginLeft={1}>
      <Text color={theme.faint}>{border("┌", "┬", "┐")}</Text>
      {renderRow(header, true, "h")}
      <Text color={theme.faint}>{border("├", "┼", "┤")}</Text>
      {rows.map((r, ri) => renderRow(r, false, String(ri)))}
      <Text color={theme.faint}>{border("└", "┴", "┘")}</Text>
    </Box>
  );
}

