            <Text key={j}>
              <Text color={theme.faint}>│ </Text>
              <Text color={theme.amber}>{cl || " "}</Text>
            </Text>
          ))}
          <Text color={theme.faint}>└</Text>
        </Box>,
      );
      continue;
    }

    if (isTableRow(line) && i + 1 < lines.length && isTableSeparator(lines[i + 1])) {
      const header = splitRow(line);
      i += 2;
      const rows: string[][] = [];
      while (i < lines.length && isTableRow(lines[i])) {
        rows.push(splitRow(lines[i]));
        i++;
      }
      blocks.push(<Table key={key++} header={header} rows={rows} />);
      continue;
    }

    if (/^\s*(-{3,}|\*{3,}|_{3,})\s*$/.test(line)) {
      blocks.push(
        <Text key={key++} color={theme.faint}>
          {"─".repeat(40)}
        </Text>,
      );
      i++;
      continue;
    }

    const header = line.match(/^(#{1,6})\s+(.*)$/);
    if (header) {
      blocks.push(
        <Text key={key++} bold color={theme.orange}>
          {header[1].length <= 2 ? header[2].toUpperCase() : header[2]}
        </Text>,
      );
      i++;
      continue;
    }

    const quote = line.match(/^\s*>\s?(.*)$/);
    if (quote) {
      blocks.push(
        <Text key={key++}>
          <Text color={theme.orange}>▌ </Text>
          <Text color={theme.dim} italic>
            {inline(quote[1])}
          </Text>
        </Text>,
      );
      i++;
      continue;
