      blocks.push(
        <Text key={key++}>
          {numbered[1]}
          <Text color={theme.orange}>{numbered[2]}. </Text>
          {inline(numbered[3])}
        </Text>,
      );
      i++;
      continue;
    }

    blocks.push(<Text key={key++}>{line.trim() === "" ? " " : inline(line)}</Text>);
    i++;
  }

  return <Box flexDirection="column">{blocks}</Box>;
}

